head.script:
scwin.init = function() {
    widgetContainer1.addWidgets([{
            id: "widget0",
            title: "위젯0",
            src: "widgetContainer_importWidgets_WPF-1746_(WSQ-2876)_content.xml",
            scope: true,
            x: 0,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget1",
            title: "위젯1",
            src: "widgetContainer_importWidgets_WPF-1746_(WSQ-2876)_content.xml",
            scope: true,
            x: 1,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget2",
            title: "위젯2",
            src: "widgetContainer_importWidgets_WPF-1746_(WSQ-2876)_content.xml",
            scope: true,
            x: 2,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        }
    ]);
    var jsonData1 = [{
            "col1": "aaa1",
            "col2": "bbb1",
            "col3": "ccc1"
        },
        {
            "col1": "aaa2",
            "col2": "bbb2",
            "col3": "ccc2"
        },
        {
            "col1": "aaa3",
            "col2": "bbb3",
            "col3": "ccc3"
        }
    ];
    var jsonData2 = [{
            "col1": "가나다1",
            "col2": "가가가1",
            "col3": "나나나1"
        },
        {
            "col1": "가나다2",
            "col2": "가가가2",
            "col3": "나나나2"
        },
        {
            "col1": "가나다3",
            "col2": "가가가3",
            "col3": "나나나3"
        }
    ];
    var jsonData3 = [{
            "col1": "11111",
            "col2": "22222",
            "col3": "44444"
        },
        {
            "col1": "11111",
            "col2": "22222",
            "col3": "55555"
        },
        {
            "col1": "11111",
            "col2": "33333",
            "col3": "66666"
        }
    ];
    WebSquare.wUnit.getObjById($p.id+'widgetContainer1_widget0_content_dataList1').setJSON(jsonData1);
    WebSquare.wUnit.getObjById($p.id+'widgetContainer1_widget1_content_dataList1').setJSON(jsonData2);
    WebSquare.wUnit.getObjById($p.id+'widgetContainer1_widget2_content_dataList1').setJSON(jsonData3);
}
scwin.onwidgetload = function(id) {
    WebSquare.wUnit.getObjById($p.id+'widgetContainer1_widget0_content_gridView').setCellColor(0, 0, "red");
    WebSquare.wUnit.getObjById($p.id+'widgetContainer1_widget0_content_gridView').setRowColor(1, "red");
};
scwin.trigger1_onclick = function(e) {
    widgetContainer1.importWidgets(null, true);
};
scwin.__isShowLogNormal = function() {
    var err = WebSquare.logger.getErrorLog();
    return !err;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 1번을 실행 후 'importWidgets'버튼을 클릭하여 초기화한다.
    //1. Execute sample file 1 and initialize it by clicking the 'importWidgets' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    // verify step 1. 위젯 데이터가 초기화되어진다.
    //1. Widget data is initialized.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#widgetContainer1_content').children().length == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. ctrl+마우스우클릭으로 로그보기를 실행하여 에러로그가 있는지 확인한다.
    //2. Run the ctrl + mouse right-click view to see if there is an error log.
    //Verify step 2. 에러로그가 보여지지 않음(이전에는 Cannot read property "x" of null 관련 에러로그가 보여짐)
    //2. Error log is not shown(Previously, Can not read property "x" of null related error log is shown)
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowLogNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
